from collections import deque
def transform(grid):
 h,w=len(grid),len(grid[0]); seen=set(); out=[[0]*w for _ in range(h)]
 for r in range(h):
  for c in range(w):
   col=grid[r][c]
   if not col or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); cells=[]
   while q:
    y,x=q.pop(); cells.append((y,x))
    for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
     if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==col: seen.add((yy,xx)); q.append((yy,xx))
   top=min(y for y,x in cells); bot=max(y for y,x in cells); shift=-top if top<6 else h-1-bot
   for y,x in cells: out[y+shift][x]=col
 return out
